use cart_rust_case::can_add;
use std::fs;

#[test]
fn test_can_add() {
    let limit: i32 = fs::read_to_string("max_items.txt").unwrap().trim().parse().unwrap();
    assert!(can_add(limit), "can_add({}) should be true", limit);
    assert!(!can_add(limit + 1), "can_add({}) should be false (stale limit not updated)", limit + 1);
}

